def loadj(path: Path) -> dict[str, Any]: return json.loads(path.read_text(encoding="utf-8"))
def writej(path: Path, obj: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True); path.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
def finding(code: str, message: str, **extra: Any) -> dict[str, Any]: return {"code": code, "severity": "P0", "message": message, **extra}
def _expect_denied(fn: Callable[[], Any]) -> bool:
    try: fn()
    except AdmissionDenied: return True
    return False

