def regression_check() -> dict[str, Any]:
    cases={}; digest="a"*64; base={"path":"/opt/fa3/staged/buzz-backend-reference","sha256":digest,"discovery_executed_provider":False}; good_route={"mcp_authority":MCP_AUTHORITY,"fa3_wrapper":True,"direct_buzz_dev_mcp":False,"workspace_containment":True,"capability_narrowing":True}
