    cases["wrapped_route_admitted"]=validate_runtime_route(good_route)["status"]=="ADMITTED_WRAPPED_ROUTE"
    cases["discovery_execution_denied"]=_expect_denied(lambda:discover_provider_candidates([{**base,"discovery_executed_provider":True}]))
